## 3. Service Provider & Registration

### `packages/larawordpress/src/LaraWordPressServiceProvider.php`
```php
<?php

namespace LaraWordPress;

use Illuminate\Support\ServiceProvider;
use LaraWordPress\Console\Commands\MakeBlockCommand;
use LaraWordPress\Services\BlockRegistryService;
use LaraWordPress\Services\PageCompilerService;

class LaraWordPressServiceProvider extends ServiceProvider
{
    public function register(): void
    {
        $this->mergeConfigFrom(__DIR__ . '/../config/larawordpress.php', 'larawordpress');

        $this->app->singleton(BlockRegistryService::class, function () {
            return new BlockRegistryService();
        });

        $this->app->singleton(PageCompilerService::class, function ($app) {
            return new PageCompilerService($app->make(BlockRegistryService::class));
        });
    }

    public function boot(): void
    {
        $this->loadRoutesFrom(__DIR__ . '/../routes/web.php');
        $this->loadViewsFrom(__DIR__ . '/../resources/views', 'larawordpress');

        if ($this->app->runningInConsole()) {
            $this->publishes([
                __DIR__ . '/../config/larawordpress.php' => config_path('larawordpress.php'),
            ], 'larawordpress-config');

            $this->publishes([
                __DIR__ . '/../resources/blocks' => config('larawordpress.blocks_path', resource_path('views/larawordpress/blocks')),
            ], 'larawordpress-blocks');

            $this->commands([
                MakeBlockCommand::class,
            ]);
        }
    }
}
```

