## 4. Block Discovery & Compiler Services

### `packages/larawordpress/src/Services/BlockRegistryService.php`
```php
<?php

namespace LaraWordPress\Services;

use Illuminate\Support\Facades\File;

class BlockRegistryService
{
    /**
     * Scan and register all blocks with block.json in configured path.
     */
    public function getAvailableBlocks(): array
    {
        $path = config('larawordpress.blocks_path');
        $packageFallback = __DIR__ . '/../../resources/blocks';

        $searchPaths = array_unique(array_filter([$path, $packageFallback]));
        $blocks = [];

        foreach ($searchPaths as $dir) {
            if (!File::isDirectory($dir)) {
                continue;
            }

            $directories = File::directories($dir);
            foreach ($directories as $blockDir) {
                $jsonFile = $blockDir . DIRECTORY_SEPARATOR . 'block.json';
                $bladeFile = $blockDir . DIRECTORY_SEPARATOR . 'view.blade.php';

                if (File::exists($jsonFile) && File::exists($bladeFile)) {
                    $metadata = json_decode(File::get($jsonFile), true);
                    $blockSlug = basename($blockDir);

                    $blocks[$blockSlug] = array_merge($metadata, [
                        'slug' => $blockSlug,
                        'view_path' => $bladeFile,
                        'dir_path' => $blockDir,
                    ]);
                }
            }
        }

        return $blocks;
    }

    public function getBlock(string $slug): ?array
    {
        $blocks = $this->getAvailableBlocks();
        return $blocks[$slug] ?? null;
    }
}
```

### `packages/larawordpress/src/Services/PageCompilerService.php`
```php
<?php

namespace LaraWordPress\Services;

use Illuminate\Support\Facades\File;
use Illuminate\Support\Str;

class PageCompilerService
{
    protected BlockRegistryService $registry;

    public function __construct(BlockRegistryService $registry)
    {
        $this->registry = $registry;
    }

    /**
     * Compile layout blocks into a clean .blade.php file.
     */
    public function compileBladeView(string $pageSlug, array $blocks): string
    {
        $destination = config('larawordpress.compiled_views_path');

        if (!File::isDirectory($destination)) {
            File::makeDirectory($destination, 0755, true);
        }

        $bladeOutput = "{{-- Generated via LaraWordPress Builder: " . now()->toDateTimeString() . " --}}\n";
        $bladeOutput .= "@extends('layouts.app')\n\n";
        $bladeOutput .= "@section('content')\n";

        foreach ($blocks as $blockItem) {
            $slug = $blockItem['slug'];
            $blockDef = $this->registry->getBlock($slug);

            if (!$blockDef) {
                continue;
            }

            $bladeTemplate = File::get($blockDef['view_path']);
            $bladeOutput .= "\n    {{-- [Block Start: {$slug}] --}}\n";
            $bladeOutput .= "    " . trim($bladeTemplate) . "\n";
            $bladeOutput .= "    {{-- [Block End: {$slug}] --}}\n\n";
        }

        $bladeOutput .= "@endsection\n";

        $sanitizedSlug = Str::slug($pageSlug, '-');
        $fullFilePath = "{$destination}/{$sanitizedSlug}.blade.php";
        File::put($fullFilePath, $bladeOutput);

        return $fullFilePath;
    }

    /**
     * Generate sample array / controller contract based on block dynamic schemas.
     */
    public function generateControllerStub(string $pageSlug, array $blocks): string
    {
        $variables = [];

        foreach ($blocks as $item) {
            $blockDef = $this->registry->getBlock($item['slug']);
            if (!$blockDef || !isset($blockDef['dynamic_binding'])) {
                continue;
            }

            $binding = $blockDef['dynamic_binding'];
            $varName = $binding['variable_name'] ?? 'data';
            $type = $binding['type'] ?? 'array';
            $fields = $binding['fields'] ?? [];

            if ($type === 'array' || $type === 'collection') {
                $sampleRow = [];
                foreach ($fields as $field => $fieldType) {
                    $sampleRow[] = "            '{$field}' => 'Sample {$field}'";
                }
                $rowCode = implode(",\n", $sampleRow);

                $variables[] = "        '{$varName}' => [\n" .
                               "            [\n{$rowCode}\n            ],\n" .
                               "        ],";
            } elseif ($type === 'associative_map') {
                $sampleMap = [];
                foreach ($fields as $field => $fieldType) {
                    $sampleMap[] = "            '{$field}' => 'Sample {$field}'";
                }
                $variables[] = "        '{$varName}' => [\n" . implode(",\n", $sampleMap) . "\n        ],";
            }
        }

        $cleanSlug = Str::slug($pageSlug, '-');
        $body = implode("\n", $variables);

        return <<<PHP
<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;

class PageController extends Controller
{
    public function {$cleanSlug}()
    {
        // Data payload defined by LaraWordPress blocks:
        \$data = [
{$body}
        ];

        return view('pages.{$cleanSlug}', \$data);
    }
}
PHP;
    }
}
```

