## 5. Web Routes & Controller

### `packages/larawordpress/routes/web.php`
```php
<?php

use Illuminate\Support\Facades\Route;
use LaraWordPress\Http\Controllers\LaraWordPressController;

Route::group([
    'prefix' => config('larawordpress.route_prefix', 'larawordpress'),
    'middleware' => config('larawordpress.middleware', ['web']),
], function () {
    Route::get('/builder', [LaraWordPressController::class, 'index'])->name('larawordpress.builder');
    Route::get('/api/blocks', [LaraWordPressController::class, 'listBlocks'])->name('larawordpress.api.blocks');
    Route::post('/api/save', [LaraWordPressController::class, 'save'])->name('larawordpress.api.save');
});
```

### `packages/larawordpress/src/Http/Controllers/LaraWordPressController.php`
```php
<?php

namespace LaraWordPress\Http\Controllers;

use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Routing\Controller;
use LaraWordPress\Services\BlockRegistryService;
use LaraWordPress\Services\PageCompilerService;

class LaraWordPressController extends Controller
{
    protected BlockRegistryService $registry;
    protected PageCompilerService $compiler;

    public function __construct(BlockRegistryService $registry, PageCompilerService $compiler)
    {
        $this->registry = $registry;
        $this->compiler = $compiler;
    }

    public function index()
    {
        $blocks = $this->registry->getAvailableBlocks();
        return view('larawordpress::builder', compact('blocks'));
    }

    public function listBlocks(): JsonResponse
    {
        return response()->json([
            'blocks' => $this->registry->getAvailableBlocks(),
        ]);
    }

    public function save(Request $request): JsonResponse
    {
        $validated = $request->validate([
            'slug' => 'required|string',
            'blocks' => 'required|array',
            'blocks.*.slug' => 'required|string',
        ]);

        $filePath = $this->compiler->compileBladeView($validated['slug'], $validated['blocks']);
        $controllerCode = $this->compiler->generateControllerStub($validated['slug'], $validated['blocks']);

        return response()->json([
            'status' => 'success',
            'saved_path' => $filePath,
            'controller_code' => $controllerCode,
        ]);
    }
}
```

