## 7. Artisan Generator Command

### `packages/larawordpress/src/Console/Commands/MakeBlockCommand.php`
```php
<?php

namespace LaraWordPress\Console\Commands;

use Illuminate\Console\Command;
use Illuminate\Support\Facades\File;

class MakeBlockCommand extends Command
{
    protected $signature = 'larawp:make-block {name : The block folder/identifier}';
    protected $description = 'Create a simple Gutenberg-style LaraWordPress block';

    public function handle(): int
    {
        $name = strtolower($this->argument('name'));
        $targetDir = config('larawordpress.blocks_path') . DIRECTORY_SEPARATOR . $name;

        if (File::exists($targetDir)) {
            $this->error("Block [{$name}] already exists!");
            return self::FAILURE;
        }

        File::makeDirectory($targetDir, 0755, true);

        // block.json
        $jsonSchema = [
            'name' => $name,
            'title' => ucfirst($name),
            'category' => 'custom',
            'description' => "Custom {$name} block",
            'dynamic_binding' => [
                'variable_name' => $name . '_data',
                'type' => 'array',
                'fields' => [
                    'title' => 'string',
                    'subtitle' => 'string',
                ],
            ],
        ];

        File::put($targetDir . '/block.json', json_encode($jsonSchema, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));

        // view.blade.php
        $bladeContent = <<<BLADE
<div class="block-{$name} p-4 border border-gray-200 rounded">
    <h3>{{ \${$name}_data['title'] ?? '{$name} Title' }}</h3>
</div>
BLADE;

        File::put($targetDir . '/view.blade.php', $bladeContent);

        $this->info("Block [{$name}] created successfully at: {$targetDir}");
        return self::SUCCESS;
    }
}
```

