        <div class="bg-white rounded-xl shadow-xl max-w-2xl w-full p-6">
            <div class="flex justify-between items-center mb-4">
                <h3 class="font-bold text-lg text-gray-800">Generated Controller Stub</h3>
                <button onclick="closeModal()" class="text-gray-400 hover:text-black">&times;</button>
            </div>
            <pre id="codeSnippet" class="bg-gray-900 text-emerald-400 p-4 rounded text-xs overflow-x-auto max-h-96"></pre>
            <div class="mt-4 flex justify-end">
                <button onclick="copyCode()" class="bg-emerald-600 text-white px-4 py-2 rounded text-sm">Copy to Clipboard</button>
            </div>
        </div>
    </div>

    <script>
        const activeBlocks = [];

        function addBlock(slug, title) {
            document.getElementById('emptyHint').style.display = 'none';
            activeBlocks.push({ slug });

            const blockNode = document.createElement('div');
            blockNode.className = 'p-4 bg-white border border-gray-300 rounded shadow-sm flex justify-between items-center';
            blockNode.innerHTML = `
                <div>
                    <span class="font-medium text-gray-800">${title}</span>
                    <span class="text-xs text-gray-400 ml-2 font-mono">(${slug})</span>
                </div>
                <button onclick="removeBlock(this, '${slug}')" class="text-red-500 hover:text-red-700 text-sm">Remove</button>
            `;
            document.getElementById('canvas').appendChild(blockNode);
        }

        function removeBlock(btn, slug) {
            const index = activeBlocks.findIndex(b => b.slug === slug);
            if (index > -1) activeBlocks.splice(index, 1);
            btn.parentElement.remove();
            if (activeBlocks.length === 0) {
                document.getElementById('emptyHint').style.display = 'block';
            }
        }

        async function savePage() {
            const slug = document.getElementById('pageSlug').value.trim();
            if (!slug) return alert('Please enter a valid page slug!');

            const res = await fetch("{{ route('larawordpress.api.save') }}", {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                },
                body: JSON.stringify({ slug, blocks: activeBlocks })
            });

            const data = await res.json();
            if (data.status === 'success') {
                document.getElementById('codeSnippet').textContent = data.controller_code;
                document.getElementById('codeModal').classList.remove('hidden');
                document.getElementById('codeModal').classList.add('flex');
            }
        }

        function closeModal() {
            document.getElementById('codeModal').classList.add('hidden');
            document.getElementById('codeModal').classList.remove('flex');
        }

        function copyCode() {
            const code = document.getElementById('codeSnippet').textContent;
            navigator.clipboard.writeText(code);
            alert('Controller snippet copied!');
        }
    </script>
</body>
</html>
